import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Appearance","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/appearance.md","filePath":"user-guide/settings/appearance.md","lastUpdated":1785993908000}'),s={name:"user-guide/settings/appearance.md"};function n(i,e,l,h,d,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h1><p>Pinned above <a href="./about.html">About</a> at the bottom of the sidebar. Two groups: <strong>Theme Mode</strong> and the theme picker itself.</p><h2 id="theme-mode" tabindex="-1">Theme Mode <a class="header-anchor" href="#theme-mode" aria-label="Permalink to &quot;Theme Mode&quot;">​</a></h2><p>Three cards, click to switch:</p><ul><li><strong>Light</strong> — a single fixed theme, filtered to light-flavored ones in the grid below.</li><li><strong>Dark</strong> — same, filtered to dark-flavored ones.</li><li><strong>Follow System</strong> (split light/dark preview) — Lertaro switches between two themes you pick — one for when Windows is in light mode, one for dark — instead of using a single fixed theme, and updates immediately whenever you toggle Windows&#39; own setting (no restart needed).</li></ul><p>Switching between <strong>Light</strong> and <strong>Dark</strong> jumps to whichever theme of that flavor you last had selected (the same remembered pick <strong>Follow System</strong> itself uses for its light/dark pair), so flipping back and forth doesn&#39;t lose your choice on either side.</p><h2 id="interface-theme" tabindex="-1">Interface Theme <a class="header-anchor" href="#interface-theme" aria-label="Permalink to &quot;Interface Theme&quot;">​</a></h2><p>With <strong>Light</strong> or <strong>Dark</strong> selected above, a single card grid lists just that flavor&#39;s themes. With <strong>Follow System</strong> selected, the grid splits into two: <strong>Light Theme</strong> and <strong>Dark Theme</strong> — each defaults to whichever matching-flavor theme happens to be installed first, since which themes exist at all depends entirely on which theme plugins are installed.</p><p>Each theme is shown as a card, not just a name: a small mock-up of the quick search window (search box plus a couple of result rows, one shown selected) rendered in that theme&#39;s own colors, so you can see what a theme actually looks like before switching to it. The active theme&#39;s card shows a checkmark badge.</p><p>Built-in and bundled theme plugins:</p><ul><li><strong>CoreExtensions</strong> (built-in) — Light, Dark, Nord, Sakura, Cyberpunk.</li><li><strong>AnimeThemes</strong> (bundled, if installed and enabled) — Neon Genesis, Sakura Bloom, Weathering Blue.</li><li><strong>Curated Themes</strong> (bundled, if installed and enabled) — ten light/dark pairs: Glacier, Terracotta, Forest, Amethyst, Crimson, Graphite, Indigo, Mint, Champagne, and Amber.</li></ul><p>Any other theme plugin can add more cards to the grid the same way.</p>',12)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
